class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        Arrays.sort(nums);

        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) {
                continue;
            }

            int left = i + 1;
            int right = nums.length - 1;
            int target = -nums[i];
            while (left < right) {
                int sum = nums[left] + nums[right];
                if (sum == target) {
                    result.add(Arrays.asList(nums[i], nums[left], nums[right]));
                    while (left < right && nums[left] == nums[left + 1]) {
                        left++;
                    }
                    while (left < right && nums[right] == nums[right - 1]) {
                        right--;
                    }
                    left++;
                    right--;
                } else if (sum < target) {
                    left++;
                } else {
                    right--;
                }
            }
        }

        return result;
    }
}

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        Set<List<Integer>> resultSet = new HashSet<>();

        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) {
                continue;
            }

            Set<Integer> seen = new HashSet<>();
            for (int j = i + 1; j < nums.length; j++) {
                int complement = -nums[i] - nums[j];
                if (seen.contains(complement)) {
                    resultSet.add(Arrays.asList(nums[i], complement, nums[j]));
                }
                seen.add(nums[j]);
            }
        }

        return new ArrayList<>(resultSet);
    }
}

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        TreeMap<Integer, Integer> counts = new TreeMap<>();
        for (int num : nums) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }

        List<Integer> values = new ArrayList<>(counts.keySet());
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < values.size(); i++) {
            int a = values.get(i);
            for (int j = i; j < values.size(); j++) {
                int b = values.get(j);
                long cLong = -(long) a - b;
                if (cLong < b || cLong < Integer.MIN_VALUE || cLong > Integer.MAX_VALUE) {
                    continue;
                }

                int c = (int) cLong;
                if (!counts.containsKey(c)) {
                    continue;
                }

                if (a == b && b == c) {
                    if (counts.get(a) >= 3) {
                        result.add(Arrays.asList(a, b, c));
                    }
                } else if (a == b) {
                    if (counts.get(a) >= 2) {
                        result.add(Arrays.asList(a, b, c));
                    }
                } else if (b == c) {
                    if (counts.get(b) >= 2) {
                        result.add(Arrays.asList(a, b, c));
                    }
                } else {
                    result.add(Arrays.asList(a, b, c));
                }
            }
        }

        return result;
    }
}

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        Arrays.sort(nums);

        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) {
                continue;
            }
            for (int j = i + 1; j < nums.length - 1; j++) {
                if (j > i + 1 && nums[j] == nums[j - 1]) {
                    continue;
                }
                int target = -nums[i] - nums[j];
                int k = binarySearch(nums, j + 1, nums.length - 1, target);
                if (k != -1) {
                    result.add(Arrays.asList(nums[i], nums[j], nums[k]));
                }
            }
        }

        return result;
    }

    private int binarySearch(int[] nums, int left, int right, int target) {
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                return mid;
            }
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
}
